SELECT A.HISTORY_ID, A.DAILY_FEE * A.DIFF - A.DAILY_FEE * A.DIFF * COALESCE(REPLACE(P.DISCOUNT_RATE, '%', ''), 0) / 100 AS FEE FROM (SELECT C.CAR_TYPE, C.DAILY_FEE, H.HISTORY_ID, DATEDIFF(H.END_DATE, H.START_DATE) + 1 AS DIFF, CASE WHEN DATEDIFF(H.END_DATE, H.START_DATE) + 1 >= 90 THEN '90일 이상' WHEN DATEDIFF(H.END_DATE, H.START_DATE) + 1 >= 30 THEN '30일 이상' WHEN DATEDIFF(H.END_DATE, H.START_DATE) + 1 >= 7 THEN '7일 이상' ELSE NULL END AS DURATION FROM CAR_RENTAL_COMPANY_CAR C JOIN CAR_RENTAL_COMPANY_RENTAL_HISTORY H ON C.CAR_ID = H.CAR_ID WHERE C.CAR_TYPE = '트럭') A LEFT JOIN CAR_RENTAL_COMPANY_DISCOUNT_PLAN P ON A.CAR_TYPE = P.CAR_TYPE AND A.DURATION = P.DURATION_TYPE ORDER BY FEE DESC, HISTORY_ID DESC;